-- the bank: h11-16 now expects «اضغط 0» on the Shafa Road number; a room-service / housekeeping extension → the team
update public.hub_test_items
   set expect = '{"action": "conversation", "steps": [{"outcome": "answer", "must_include": ["0"], "must_not_include": ["سيكمل معك", "333"]}]}'::jsonb
 where key = 'h11-16' and expect = '{"action": "conversation", "steps": [{"outcome": ["handoff", "answer_handoff"], "must_not_include": ["اضغط 0", "333"]}]}'::jsonb;
do $$
declare v_sort integer := coalesce((select max(sort) + 1 from public.hub_test_items), 0);
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($h11c_bank$[{"key":"h11-22","unit":"shafa-road","language":"ar","messages":["كم تحويلة خدمة الغرف من تلفون الغرفة؟"],"expect":{"action":"conversation","steps":[{"outcome":["handoff","answer_handoff"],"must_not_include":["اضغط 0","333","222"]}]},"note":"Ahmed, 24 Nov 2026: a room-service extension is unknown at either branch — the team, never an invented extension","tags":["conversation","h11","h11c","phones"],"context":{}},{"key":"h11-23","unit":"airport-road","language":"en","messages":["What's the extension for housekeeping from the room phone?"],"expect":{"action":"conversation","steps":[{"outcome":["handoff","answer_handoff"],"must_not_include":["dial 0","333","222"]}]},"note":"Ahmed, 24 Nov 2026: a housekeeping extension is unknown — the team","tags":["conversation","h11","h11c","phones"],"context":{}},{"key":"h11-24","unit":"shafa-road","language":"en","messages":["How do I call reception from the phone in my room?"],"expect":{"action":"conversation","steps":[{"outcome":"answer","must_include":["0"],"must_not_include":["333","222"]}]},"note":"Ahmed, 24 Nov 2026: reception from the room phone is 0 at Shafa Road too","tags":["conversation","h11","h11c","phones"],"context":{}}]$h11c_bank$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;
